using System;
using System.IO;
using System.Text.RegularExpressions;
namespace NzbDrone.Core.MediaFiles.RecoverableOperations { public sealed record RecoverableOperationStagingPaths(string Root, string Source, string Backup, string Candidate); public static class RecoverableOperationStagingPolicy { const string DirectoryName = ".radarr-recovery"; static readonly Regex SafeKey = new("^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$", RegexOptions.Compiled | RegexOptions.CultureInvariant); public static RecoverableOperationStagingPaths GetPaths(string moviePath, string operationKey) { if (string.IsNullOrWhiteSpace(moviePath) || !Path.IsPathRooted(moviePath)) throw new ArgumentException("Movie path must be rooted.", nameof(moviePath)); if (string.IsNullOrWhiteSpace(operationKey) || !SafeKey.IsMatch(operationKey) || operationKey == "." || operationKey == "..") throw new ArgumentException("Operation key is not path safe.", nameof(operationKey)); var movieRoot = Path.GetFullPath(moviePath); var root = Path.GetFullPath(Path.Combine(movieRoot, DirectoryName, operationKey)); var prefix = movieRoot.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar) + Path.DirectorySeparatorChar; if (!root.StartsWith(prefix, StringComparison.Ordinal)) throw new ArgumentException("Staging path escapes the movie path.", nameof(operationKey)); root = root.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar) + Path.DirectorySeparatorChar; return new(root, Child(root, "source"), Child(root, "backup"), Child(root, "candidate")); } static string Child(string root, string name) { var child = Path.GetFullPath(Path.Combine(root, name)); if (!child.StartsWith(root, StringComparison.Ordinal)) throw new InvalidOperationException("Staging child escaped its root."); return child; } } }
